import * as THREE from 'three/webgpu';
import { color, mix, positionGeometry, clamp, add, mul } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  const masterTL = gsap.timeline();

  const W = 6.8, H = 2.0, HAIRLINE = 0.006, BASE = 0.25;

  // Background plane with vertical gradient
  const bgGeo = new THREE.PlaneGeometry(W, H);
  const posY = positionGeometry().y;
  const normY = clamp(mul(add(posY, H / 2), 1 / H), 0, 1);
  const bgMat = new THREE.MeshStandardNodeMaterial({
    colorNode: mix(color(0x121218), color(0x0b0b10), normY),
    roughnessValue: 0.6,
    metalnessValue: 0.2,
    transparent: true,
    opacity: 0,
  });
  const bg = new THREE.Mesh(bgGeo, bgMat);
  root.add(bg);

  // Top hairline rule
  const hlGeo = new THREE.PlaneGeometry(W, HAIRLINE);
  const hlMat = new THREE.MeshBasicNodeMaterial({
    colorNode: color(0x23232b),
    transparent: true,
    opacity: 0,
  });
  const topHL = new THREE.Mesh(hlGeo, hlMat);
  topHL.position.set(0, H / 2 - HAIRLINE / 2, 0.001);
  root.add(topHL);

  // Bottom hairline rule (0.25 above legal)
  const botHL = new THREE.Mesh(hlGeo, hlMat.clone());
  botHL.position.set(0, -H / 2 + 0.375 + HAIRLINE / 2, 0.001);
  root.add(botHL);

  // Accent bar beneath wordmark
  const accentGeo = new THREE.PlaneGeometry(0.3, 0.02);
  const accentMat = new THREE.MeshBasicNodeMaterial({
    colorNode: color(0xff2a38),
    transparent: true,
    opacity: 0,
  });
  const accent = new THREE.Mesh(accentGeo, accentMat);
  accent.position.set(-W / 2 + 1.15, H / 2 - 0.49, 0.002);
  root.add(accent);

  const allText = [];
  const linkMeshes = [];

  const renderText = (text, fontSize, fontWeight, letterSpacing, isLink = false) => {
    if (!ctx.fontAtlas) return null;
    try {
      const mesh = ctx.fontAtlas.render(text, {
        fontSize,
        fontWeight,
        letterSpacing,
        color: 0xe8ecf2,
      });
      if (!mesh) return null;
      mesh.position.z = 0.002;
      mesh.traverse(child => {
        if (child.material && typeof child.material.opacity === 'number') {
          child.material.transparent = true;
          child.material.opacity = 0;
        }
      });
      if (isLink) linkMeshes.push(mesh);
      allText.push(mesh);
      root.add(mesh);
      return mesh;
    } catch (e) {
      return null;
    }
  };

  // Wordmark
  const wordmark = renderText('NOVA ATELIER', 34, 600, 0.02);
  if (wordmark) wordmark.position.set(-W / 2 + 1, H / 2 - BASE, 0.002);

  // Three column layout
  const columns = [
    { header: 'ATELIER', links: ['Features', 'Collection', 'Pricing'] },
    { header: 'COMPANY', links: ['Journal', 'Visit the Atelier', 'Contact'] },
    { header: 'LEGAL', links: ['Privacy', 'Terms', 'Warranty'] },
  ];

  const colStartX = -W / 2 + 2.375;
  const colWidth = 1.2, colGutter = 0.375;

  columns.forEach((col, colIdx) => {
    const colX = colStartX + colIdx * (colWidth + colGutter);
    const headerY = H / 2 - BASE;

    // Column header
    const header = renderText(col.header, 9, 700, 0.12);
    if (header) header.position.set(colX, headerY, 0.002);

    // Column links
    col.links.forEach((linkText, linkIdx) => {
      const linkY = headerY - BASE * (linkIdx + 1) - 0.1;
      const link = renderText(linkText, 13, 400, 0, true);
      if (link) link.position.set(colX, linkY, 0.002);
    });
  });

  // Legal line
  const legal = renderText('(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.', 9, 400, 0.04);
  if (legal) legal.position.set(-W / 2 + 0.5, -H / 2 + 0.375 - BASE, 0.002);

  // Hover handlers for links
  root.userData.handlers = {
    onPointerEnter: () => {
      linkMeshes.forEach(mesh => {
        gsap.to(mesh.material.color, {
          hex: '#ff2a38',
          duration: 0.14,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        gsap.to(mesh.position, {
          z: 0.02,
          duration: 0.14,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
      });
    },
    onPointerLeave: () => {
      linkMeshes.forEach(mesh => {
        gsap.to(mesh.material.color, {
          hex: '#e8ecf2',
          duration: 0.14,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        gsap.to(mesh.position, {
          z: 0.002,
          duration: 0.14,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
      });
    },
  };

  // Fade-up animation
  root.position.y = 0.2;
  const allMaterials = [bgMat, hlMat, accentMat];
  root.traverse(child => {
    if (child.material && !allMaterials.includes(child.material)) {
      allMaterials.push(child.material);
    }
  });

  masterTL.fromTo(
    root.position,
    { y: 0.2 },
    { y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    0
  );
  masterTL.to(
    allMaterials,
    { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    0
  );

  // Cleanup
  root.userData.cleanup = () => {
    masterTL.kill();
    gsap.killTweensOf([root, root.position, ...linkMeshes]);

    [bgGeo, hlGeo, accentGeo].forEach(g => g.dispose());
    [bgMat, hlMat, accentMat].forEach(m => m.dispose());

    root.traverse(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material && !allMaterials.includes(child.material)) {
        child.material.dispose();
      }
    });
  };

  return root;
}
